// Get the text output from the AI node
const aiResponse = $input.first().json.text;

// Initialize an object to hold the final, structured data for Google Sheets
const result = {
  "Script Recreation": null,
  "Video Title": null,
  "Thumbnail Ideas": null,
  "Tags & SEO": null,
  "Video Description": null,
  "Virality Optimization": null
};

// Define the exact headings the AI response uses
const headings = {
  "Script Recreation": "### SCRIPT ###",
  "Video Title": "### TITLES ###",
  "Thumbnail Ideas": "### THUMBNAILS ###",
  "Tags & SEO": "### TAGS ###",
  "Video Description": "### DESCRIPTION ###",
  "Virality Optimization": "### VIRALITY ###"
};

// 1. THE FIX: Split the text based on the "### HEADING ###" pattern.
// This regex looks for the pattern and splits the text *before* it, keeping the heading with its content.
const sections = aiResponse.split(/(?=###\s[A-Z\s&]+\s###)/);

// 2. Process each section to identify and extract its content
sections.forEach(section => {
  const trimmedSection = section.trim();

  // Check which heading the section starts with
  for (const key in headings) {
    if (trimmedSection.startsWith(headings[key])) {
      // If a match is found, remove the heading tag and store the clean content
      const content = trimmedSection.replace(headings[key], '').trim();
      result[key] = content;
      break; // Move to the next section
    }
  }
});

// 3. Return the final structured object, ready for Google Sheets
return {
  json: result
};

